def transform(grid):
    h, w = len(grid), len(grid[0])
    # Colored diagonal marks determine a repeating four-color diagonal pattern.
    # For anti-diagonals, use the marked sums to assign the stripe colors.
    marks = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c]:
                marks[r + c] = grid[r][c]

    # Extend the observed diagonal colors cyclically by their order.
    sums = sorted(marks)
    colors = [marks[s] for s in sums]
    if len(colors) < 4:
        colors = colors + [0] * (4 - len(colors))

    # The four marked stripes define a period-four sequence across diagonals.
    base = sums[0] % 4
    lookup = {}
    for s, color in marks.items():
        lookup[s % 4] = color
    # Fill unrepresented residues by cycling through the observed stripe colors.
    for i in range(4):
        lookup.setdefault((base + i) % 4, colors[i % len(colors)])
    return [[lookup[(r + c) % 4] for c in range(w)] for r in range(h)]
